function prepare({ body, listId, customFields }) {
  const v = body;
  if (!v || typeof v !== "object" || typeof v["4"] !== "string" || !v["4"].includes("@"))
    throw Error("Email required");
  if (!Number.isSafeInteger(listId) || listId <= 0) throw Error("Configure opt-in process ID");
  const keys = ["feedback", "rating", "comments", "choice", "webinar"];
  if (
    !customFields ||
    keys.some((k) => !/^field\d+$/.test(customFields[k] || "")) ||
    new Set(keys.map((k) => customFields[k])).size !== 5
  )
    throw Error("Configure five distinct custom fields");
  const birthday = Date.parse(String(v["6"]) + "T00:00:00Z"),
    match = /^(\d{2})\.(\d{2})\.(\d{4}) (\d{2}):(\d{2})$/.exec(v["13"] || "");
  if (!Number.isFinite(birthday) || !match) throw Error("Invalid dates");
  const [, day, month, year, hour, minute] = match,
    webinar = Date.parse(`${year}-${month}-${day}T${hour}:${minute}:00Z`);
  if (!Number.isFinite(webinar)) throw Error("Invalid webinar date");
  const rating = Number(v["8"]);
  if (!Number.isFinite(rating)) throw Error("Invalid rating");
  let extra = [];
  try {
    extra = v["11"] ? JSON.parse(v["11"]) : [];
  } catch {
    extra = [];
  }
  if (!Array.isArray(extra)) extra = [extra];
  const tags = [v["8"] || null, v["13"] || null, ...extra].filter((x) => x !== null);
  if (tags.some((x) => typeof x !== "string" || !x.trim())) throw Error("Invalid tag");
  const fields = {
    fieldFirstName: String(v["1"] || ""),
    fieldLastName: String(v["3"] || ""),
    fieldBirthday: String(Math.floor(birthday / 1000)),
    [customFields.feedback]: String(v["7"] || ""),
    [customFields.rating]: String(rating * 100),
    [customFields.comments]: String(v["9"] || ""),
    [customFields.choice]: String(v["12.1"] || ""),
    [customFields.webinar]: String(Math.floor(webinar / 1000)),
  };
  const phone = String(v["5"] || "")
    .replace(/^\+/, "00")
    .replace(/[^0-9]/g, "");
  return {
    email: v["4"],
    subscriber: { email: v["4"], ...(phone ? { smsnumber: phone } : {}), listid: listId, fields },
    tags: [...new Set(tags)],
  };
}

const p = prepare({
  body: $json.body,
  listId: 1,
  customFields: {
    feedback: "field101",
    rating: "field102",
    comments: "field103",
    choice: "field104",
    webinar: "field105",
  },
});
return {
  json: {
    mobile_number: p.subscriber.smsnumber || "",
    birthday: p.subscriber.fields.fieldBirthday,
    webinar_rating: p.subscriber.fields.field102,
    webinar_choice: p.subscriber.fields.field105,
  },
};

