const names = $("Split Out Gravityforms tags")
  .all()
  .map((x) => x.json.tags);
const existing = $("Get list of all existing tags")
  .all()
  .map((x) => x.json)
  .filter((x) => x.id != null && typeof x.value === "string");
return names.map((name) => {
  const hit = existing.find((x) => x.value === name);
  return { json: { name, exist: !!hit, tag_id: hit?.id ?? null } };
});
